// Seeds round 1. Everything the loop needs to carry between iterations lives
// in this one object — round counter, current draft, latest critique, and the
// score history. Keeping loop state in a single explicit shape is what makes
// the back-edge to 'Prepare round' safe to reason about.
const cfg = $('Set Workflow Parameters').first().json;
const brief = String($json.brief || $json.chatInput || cfg.defaultBrief || '').trim();
if (!brief) throw new Error('No brief provided. Pass {brief: "..."} or set defaultBrief in Settings.');

return [{ json: {
  brief,
  round: 1,
  previous_score: 'n/a (first round)',
  revision_instructions: 'This is the first draft. Write it from the brief.',
  current_draft: '',
  score_history: [],
  critique_history: [],
  started_at: new Date().toISOString().slice(0, 19).replace('T', ' '),
} }];

// Loop head. Receives the initial state on the first pass and the updated
// state from 'Build next round' on every subsequent pass. Deliberately a
// pass-through: keeping the head simple makes the cycle easy to trace in the
// editor.
return [{ json: { ...$json } }];

const w = $json.output ?? $json;
const state = $('Prepare Round Data').first().json;
return [{ json: {
  ...state,
  current_draft: w.draft ?? '',
  writer_self_assessment: w.self_assessment ?? '',
  deliberate_deviations: (w.deliberate_deviations || []).join(' | '),
  needs_from_human: (w.needs_from_human || []).join(' | '),
  word_count_estimate: w.word_count_estimate ?? null,
} }];

const c = $json.output ?? $json;
const state = $('Capture Draft Output').first().json;
const cfg = $('Set Workflow Parameters').first().json;

const score = Number(c.score);
const mustFix = c.must_fix || [];
const threshold = Number(cfg.approvalScore || 80);

// Two independent conditions must BOTH hold to approve. A high score with an
// outstanding must_fix is not an approval — the rubric and the blocking list
// are separate signals and the stricter one governs.
const meets_bar = !isNaN(score) && score >= threshold && mustFix.length === 0;

const history = [...(state.score_history || []), isNaN(score) ? null : score];

// Detect a stalled loop: if the score has not moved meaningfully in two
// consecutive rounds, more rounds are unlikely to help and the human should
// look at it instead of burning the remaining budget.
let stalled = false;
if (history.length >= 3) {
  const [a, b, cLast] = history.slice(-3);
  if ([a, b, cLast].every(n => typeof n === 'number')) {
    stalled = Math.abs(cLast - b) < 3 && Math.abs(b - a) < 3;
  }
}

return [{ json: {
  ...state,
  score: isNaN(score) ? null : score,
  score_reason: c.score_reason ?? '',
  must_fix: mustFix.join(' | '),
  must_fix_count: mustFix.length,
  would_improve: (c.would_improve || []).join(' | '),
  what_works: (c.what_works || []).join(' | '),
  house_rule_violations: (c.house_rule_violations || []).join(' | '),
  critic_verdict: c.verdict ?? 'revise',
  meets_bar,
  stalled,
  score_history: history,
  critique_history: [...(state.critique_history || []),
                     `R${state.round}: ${score} — ${(c.must_fix || []).length} must-fix`],
} }];

// The single place where "keep going or stop" is decided. Three independent
// stop conditions, evaluated in priority order — each produces a different
// exit_reason so the ledger records WHY the loop ended, not just that it did.
const s = $json;
const cfg = $('Set Workflow Parameters').first().json;
const maxRounds = Number(cfg.maxRounds || 3);

let should_continue = false;
let exit_reason = '';

if (s.meets_bar) {
  exit_reason = 'APPROVED';
} else if (s.round >= maxRounds) {
  // Hard cap. This is the condition that guarantees the loop terminates
  // regardless of what the two agents decide between them.
  exit_reason = 'ROUND_LIMIT';
} else if (s.stalled) {
  exit_reason = 'STALLED';
} else {
  should_continue = true;
  exit_reason = 'CONTINUING';
}

return [{ json: { ...s, should_continue, exit_reason } }];

// Builds the next round's state, including the critique formatted as revision
// instructions. This is the node the loop's back-edge feeds into.
const s = $json;
const lines = [];
lines.push(`Your previous draft scored ${s.score}/100. ${s.score_reason || ''}`);
if (s.must_fix) {
  lines.push('');
  lines.push('MUST FIX — these block approval:');
  String(s.must_fix).split(' | ').forEach(x => lines.push(`- ${x}`));
}
if (s.house_rule_violations) {
  lines.push('');
  lines.push('HOUSE RULE VIOLATIONS:');
  String(s.house_rule_violations).split(' | ').forEach(x => lines.push(`- ${x}`));
}
if (s.would_improve) {
  lines.push('');
  lines.push('Would improve (optional):');
  String(s.would_improve).split(' | ').forEach(x => lines.push(`- ${x}`));
}
if (s.what_works) {
  lines.push('');
  lines.push(`Keep: ${s.what_works}`);
}
lines.push('');
lines.push('--- YOUR PREVIOUS DRAFT ---');
lines.push(s.current_draft || '');
lines.push('--- END PREVIOUS DRAFT ---');

return [{ json: {
  brief: s.brief,
  round: Number(s.round) + 1,
  previous_score: s.score,
  revision_instructions: lines.join('\n'),
  current_draft: s.current_draft,
  score_history: s.score_history,
  critique_history: s.critique_history,
  started_at: s.started_at,
} }];

const s = $json;
const EXIT = {
  APPROVED: '✅ Approved by the critic',
  ROUND_LIMIT: '⏹️ Stopped at the round limit — not approved',
  STALLED: '⚠️ Stopped: score stopped improving — not approved',
};

const L = [];
L.push(`${EXIT[s.exit_reason] || s.exit_reason} · round ${s.round} of ${$('Set Workflow Parameters').first().json.maxRounds} · final score ${s.score}/100`);
L.push('');
L.push(s.current_draft || '(no draft produced)');

const extra = [];
if (s.needs_from_human) {
  extra.push('');
  extra.push('**Needs a human to supply:**');
  String(s.needs_from_human).split(' | ').forEach(x => extra.push(`• ${x}`));
}
if (s.exit_reason !== 'APPROVED' && s.must_fix) {
  extra.push('');
  extra.push('**Outstanding must-fix points:**');
  String(s.must_fix).split(' | ').forEach(x => extra.push(`• ${x}`));
}
if (s.deliberate_deviations) {
  extra.push('');
  extra.push(`**Writer deliberately deviated:** ${s.deliberate_deviations}`);
}
extra.push('');
extra.push(`**Score history:** ${(s.score_history || []).join(' → ')}`);

return [{ json: { ...s,
  output: L.join('\n') + '\n' + extra.join('\n'),
  completed_at: new Date().toISOString().slice(0, 19).replace('T', ' '),
} }];
